    Bug 2052995 - Clean up imported certificates in test browser_displayVarious.js. r=edicharry

    Differential Revision: https://phabricator.services.mozilla.com/D310733

diff --git a/mail/test/browser/smime/browser_displayVarious.js b/mail/test/browser/smime/browser_displayVarious.js
index 6cc36176ea0..21596e9d495 100644
--- a/mail/test/browser/smime/browser_displayVarious.js
+++ b/mail/test/browser/smime/browser_displayVarious.js
@@ -48,6 +48,17 @@ add_setup(async function () {
     new FileUtils.File(getTestFilePath("data/Alice.p12")),
     "nss"
   );
+
+  registerCleanupFunction(function () {
+    const certDB = Cc["@mozilla.org/security/x509certdb;1"].getService(
+      Ci.nsIX509CertDB
+    );
+    for (const cert of certDB.getCerts()) {
+      if (["NSS Test CA (RSA)", "Bob", "Alice"].includes(cert.commonName)) {
+        certDB.deleteCertificate(cert);
+      }
+    }
+  });
 });

